import{_ as d,c as e,o as a,ae as o}from"./chunks/framework.BnYZi0O_.js";const _=JSON.parse('{"title":"环境变量","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/environment-variables.md","filePath":"configuration/environment-variables.md"}'),r={name:"configuration/environment-variables.md"};function i(s,t,c,n,h,l){return a(),e("div",null,t[0]||(t[0]=[o(`<h1 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h1><p>xiaozhi-mcphub <strong>1.1.0</strong> 通过环境变量与（可选）<code>mcp_settings.json</code> / 数据库系统配置共同生效。<br> 与旧版文档的重要差异：数据库连接使用 <strong><code>DB_URL</code></strong>。<br> 从 <strong>v1.0.3</strong> 升级时旧名 <strong><code>DATABASE_URL</code> 仍可读</strong>（会打 deprecation 警告）；请尽快改成 <code>DB_URL</code>。详见 <a href="/xiaozhi-mcphub/configuration/upgrade-from-v103.html">从 v1.0.3 升级</a>。</p><h2 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to &quot;核心&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>PORT</code></td><td><code>3000</code></td><td>HTTP 端口</td></tr><tr><td><code>NODE_ENV</code></td><td><code>development</code></td><td><code>development</code> / <code>production</code> / <code>test</code></td></tr><tr><td><code>BASE_PATH</code></td><td>空</td><td>子路径部署，如 <code>/mcphub</code></td></tr><tr><td><code>READONLY</code></td><td><code>false</code></td><td><code>true</code> 时禁止修改类操作</td></tr><tr><td><code>INIT_TIMEOUT</code></td><td><code>300000</code></td><td>初始化超时（ms）</td></tr><tr><td><code>DEFAULT_REQUEST_TIMEOUT</code></td><td><code>60000</code></td><td>上游 MCP 默认超时（ms）</td></tr><tr><td><code>MCPHUB_SETTING_PATH</code></td><td>自动检测</td><td>设置文件路径</td></tr><tr><td><code>INSTALL_BASE_URL</code></td><td>-</td><td>公网安装/回调基址；Dashboard 里保存的 baseUrl 优先</td></tr></tbody></table><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>PostgreSQL 连接串。配置后通常启用数据库模式；<strong>小智端点等依赖 DB</strong></td></tr><tr><td><code>DATABASE_URL</code></td><td><strong>兼容旧版</strong>：与 <code>DB_URL</code> 同义；仅当 <code>DB_URL</code> 未设时生效</td></tr><tr><td><code>USE_DB</code></td><td>可选，显式开关 DB 模式（一般随 <code>DB_URL</code> / <code>DATABASE_URL</code> 自动判断）</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postgres://xiaozhi:密码@127.0.0.1:5432/xiaozhi_mcphub</span></span></code></pre></div><p>智能路由向量存储使用同一套 PostgreSQL（需 <strong>pgvector</strong> 扩展）。</p><h2 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>JWT_SECRET</code></td><td>JWT 签名密钥（生产必填；开发可自动生成）</td></tr><tr><td><code>ADMIN_PASSWORD</code></td><td><strong>仅首次空用户库</strong>时创建 <code>admin</code> 的密码；之后忽略</td></tr></tbody></table><p>密码策略（注册 / 改密 / 重置）：至少 8 位，含字母、数字与特殊字符。界面与 API 使用 i18n 错误码。</p><h3 id="better-auth-可选-github-google-oidc" tabindex="-1">Better Auth（可选：GitHub / Google / OIDC） <a class="header-anchor" href="#better-auth-可选-github-google-oidc" aria-label="Permalink to &quot;Better Auth（可选：GitHub / Google / OIDC）&quot;">​</a></h3><p>需 <strong><code>DB_URL</code></strong>（Better Auth 会话走 PostgreSQL）。非敏感项也可写在 <code>systemConfig.auth.betterAuth</code>，优先级：环境变量 &gt; 系统配置 &gt; 默认。</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>BETTER_AUTH_ENABLED</code></td><td>总开关</td></tr><tr><td><code>BETTER_AUTH_URL</code></td><td>公网 URL（回调）</td></tr><tr><td><code>BETTER_AUTH_BASE_PATH</code></td><td>默认 <code>/api/auth/better</code></td></tr><tr><td><code>BETTER_AUTH_TRUSTED_ORIGINS</code></td><td>额外可信来源</td></tr><tr><td><code>BETTER_AUTH_GOOGLE_ENABLED</code> + <code>GOOGLE_CLIENT_ID</code> / <code>GOOGLE_CLIENT_SECRET</code></td><td>Google</td></tr><tr><td><code>BETTER_AUTH_GITHUB_ENABLED</code> + <code>GITHUB_CLIENT_ID</code> / <code>GITHUB_CLIENT_SECRET</code></td><td>GitHub</td></tr><tr><td><code>BETTER_AUTH_OIDC_ENABLED</code> 等</td><td>通用 OIDC（Keycloak / Authentik / Dex…）</td></tr></tbody></table><p>第三方登录映射到本地用户时<strong>不会自动授予管理员</strong>。</p><h3 id="邮件-注册验证-找回密码" tabindex="-1">邮件（注册验证 / 找回密码） <a class="header-anchor" href="#邮件-注册验证-找回密码" aria-label="Permalink to &quot;邮件（注册验证 / 找回密码）&quot;">​</a></h3><p>在控制台 <strong>设置 → 邮件 (SMTP)</strong> 配置，或写入系统配置。启用且 SMTP 完整时：</p><ul><li>注册可要求邮箱并发送验证信</li><li>支持忘记密码重置链接</li><li><code>getPublicConfig</code> 会暴露 <code>emailEnabled</code>（不含密钥）给前端</li></ul><h2 id="智能路由" tabindex="-1">智能路由 <a class="header-anchor" href="#智能路由" aria-label="Permalink to &quot;智能路由&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>SMART_ROUTING_ENABLED</code></td><td>是否启用</td></tr><tr><td><code>OPENAI_API_KEY</code></td><td>Embedding 等</td></tr><tr><td><code>OPENAI_API_BASE_URL</code></td><td>可选自定义网关</td></tr><tr><td><code>OPENAI_API_EMBEDDING_MODEL</code></td><td>如 <code>text-embedding-3-small</code></td></tr></tbody></table><p><strong><code>dbUrl</code>（向量库）为实例级基础设施</strong>，仅管理员可在设置中查看/修改；普通用户可覆盖个人 API Key 等（见多账户配置）。</p><h2 id="小智重连-可选" tabindex="-1">小智重连（可选） <a class="header-anchor" href="#小智重连-可选" aria-label="Permalink to &quot;小智重连（可选）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>XIAOZHI_AGGRESSIVE_RECONNECT</code></td><td>快速重连（弱退避）</td></tr><tr><td><code>XIAOZHI_RECONNECT_INTERVAL</code></td><td>快速重连间隔 ms</td></tr><tr><td><code>XIAOZHI_MAX_INFINITE_RETRIES</code></td><td>无限重连上限（0=不限制）</td></tr><tr><td><code>XIAOZHI_SLEEP_THRESHOLD</code> / <code>XIAOZHI_SLEEP_INTERVAL</code></td><td>休眠阈值与间隔</td></tr><tr><td><code>XIAOZHI_MAX_CONCURRENT_RECONNECTS</code></td><td>同时重连上限（默认 3，背压）</td></tr><tr><td><code>XIAOZHI_RECONNECT_JITTER_RATIO</code></td><td>重连延迟抖动 0–1（默认 0.2）</td></tr></tbody></table><p>端点级重连参数也可在 UI 中配置。详见 <a href="/xiaozhi-mcphub/configuration/xiaozhi.html">小智接入</a>。</p><h2 id="更新检查" tabindex="-1">更新检查 <a class="header-anchor" href="#更新检查" aria-label="Permalink to &quot;更新检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>DISABLE_UPDATE_CHECK</code></td><td><code>true</code> 关闭关于弹窗的更新检查</td></tr><tr><td><code>MCPHUB_GITHUB_REPO</code></td><td>默认 <code>huangjunsen0406/xiaozhi-mcphub</code></td></tr><tr><td><code>MCPHUB_GITHUB_TOKEN</code> / <code>GITHUB_TOKEN</code></td><td>提高 GitHub API 限额（私有仓需要）</td></tr><tr><td><code>MCPHUB_UPDATE_CHECK_TIMEOUT_MS</code></td><td>请求超时</td></tr><tr><td><code>MCPHUB_UPDATE_CHECK_CACHE_TTL_SECONDS</code></td><td>进程内缓存 TTL</td></tr></tbody></table><p>更新源为本仓库 <strong>GitHub Releases</strong>（无 npm 兜底）。</p><h2 id="代理与其它" tabindex="-1">代理与其它 <a class="header-anchor" href="#代理与其它" aria-label="Permalink to &quot;代理与其它&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code></td><td>出站代理</td></tr><tr><td><code>NPM_REGISTRY</code></td><td>安装 MCP 依赖时的 npm 源（镜像内）</td></tr></tbody></table><h2 id="示例-env" tabindex="-1">示例 <code>.env</code> <a class="header-anchor" href="#示例-env" aria-label="Permalink to &quot;示例 \`.env\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NODE_ENV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JWT_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">replace-with-long-random-string</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postgres://xiaozhi:xiaozhi123456@127.0.0.1:5432/xiaozhi_mcphub</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ADMIN_PASSWORD=only-on-first-bootstrap</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SMART_ROUTING_ENABLED=false</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># DISABLE_UPDATE_CHECK=false</span></span></code></pre></div><p>本地示例还可参考仓库根目录 <code>.env.example</code>。</p>`,32)]))}const p=d(r,[["render",i]]);export{_ as __pageData,p as default};
